select * from Pre_Project where replace(replace(P_Name, ' ', ''), ' ', '') in
#{projectName}
order by State_Time desc

select *
from Pre_Project
where
    (
        replace(replace(replace(replace(P_Name, ' ', ''), '　', ''), '(', '（'), ')', '）') = #{projectName}
        or replace(replace(replace(replace(P_Name, ' ', ''), '　', ''), '(', '（'), ')', '）') like concat('%', #{projectName}, '%')
        or replace(replace(replace(replace(P_Project_Abbreviation, ' ', ''), '　', ''), '(', '（'), ')', '）') = #{projectName}
        or replace(replace(replace(replace(P_Project_Abbreviation, ' ', ''), '　', ''), '(', '（'), ')', '）') like concat('%', #{projectName}, '%')
        or replace(replace(replace(replace(P_Original_Name, ' ', ''), '　', ''), '(', '（'), ')', '）') = #{projectName}
        or replace(replace(replace(replace(P_Original_Name, ' ', ''), '　', ''), '(', '（'), ')', '）') like concat('%', #{projectName}, '%')
    )
order by State_Time desc
